import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"55、【丰】 离下震上","description":"横渠易说 - 55、【丰】 离下震上","frontmatter":{"title":"55、【丰】 离下震上","description":"横渠易说 - 55、【丰】 离下震上"},"headers":[],"relativePath":"zh/classics/hengqu/057.md","filePath":"zh/classics/hengqu/057.md"}'),l={name:"zh/classics/hengqu/057.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_55、【丰】-离下震上" tabindex="-1">55、【丰】 离下震上 <a class="header-anchor" href="#_55、【丰】-离下震上" aria-label="Permalink to “55、【丰】 离下震上”">​</a></h1><p>宜日中，不宜过中也。</p><h3 id="彖曰-丰-大也-明以动-故丰。-王假之-尚大也-勿忧宜日中-宜照天下也。日中则昃-月盈则食-天地盈虚-与时消息-而况于人乎-况于鬼神乎" tabindex="-1">彖曰：丰，大也，明以动，故丰。“王假之”，尚大也；“勿忧宜日中”，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎!况于鬼神乎! <a class="header-anchor" href="#彖曰-丰-大也-明以动-故丰。-王假之-尚大也-勿忧宜日中-宜照天下也。日中则昃-月盈则食-天地盈虚-与时消息-而况于人乎-况于鬼神乎" aria-label="Permalink to “彖曰：丰，大也，明以动，故丰。“王假之”，尚大也；“勿忧宜日中”，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎!况于鬼神乎!”">​</a></h3><p>月盈则食，中弦盈之极也，此人鬼所以恶盈祸盈也。</p><h3 id="象曰-雷电皆至-丰-君子以折狱致刑。" tabindex="-1">象曰：雷电皆至，丰，君子以折狱致刑。 <a class="header-anchor" href="#象曰-雷电皆至-丰-君子以折狱致刑。" aria-label="Permalink to “象曰：雷电皆至，丰，君子以折狱致刑。”">​</a></h3><p>盛明如天，大之至也，动于上而明于下，故折狱致刑，民不惑矣。</p><h3 id="初九-遇其配主-虽旬无咎-往有尚。-象曰-虽旬无咎-过旬灾也。" tabindex="-1">初九，遇其配主，虽旬无咎，往有尚。 象曰：“虽旬无咎”，过旬灾也。 <a class="header-anchor" href="#初九-遇其配主-虽旬无咎-往有尚。-象曰-虽旬无咎-过旬灾也。" aria-label="Permalink to “初九，遇其配主，虽旬无咎，往有尚。 象曰：“虽旬无咎”，过旬灾也。”">​</a></h3><p>所之在进，光大其宜也，故往而有尚。非均是阳爻，则蔀暗之灾，与六二疑疾无以异也。</p><h3 id="六二-丰其蔀-日中见斗-往得疑疾-有孚发若-吉。-象曰-有孚发若-信以发志也。" tabindex="-1">六二，丰其蔀，日中见斗，往得疑疾，有孚发若，吉。 象曰：“有孚发若”，信以发志也。 <a class="header-anchor" href="#六二-丰其蔀-日中见斗-往得疑疾-有孚发若-吉。-象曰-有孚发若-信以发志也。" aria-label="Permalink to “六二，丰其蔀，日中见斗，往得疑疾，有孚发若，吉。 象曰：“有孚发若”，信以发志也。”">​</a></h3><p>凡言往者，皆进而之上也。初进而上则(进)［遇］阳而有尚。二既以阴居阴而又所应亦阴，故往无所发，愈增疑疾，能不私于累，信然接物乃吉。宜日中而所应得阴，故曰“见斗”，五在君位，故以斗喻夜见之象。</p><h3 id="九三-丰其沛-日中见沫-折其右肱-无咎。-象曰-丰其沛-不可大事也。-折其右肱-终不可用也。" tabindex="-1">九三，丰其沛，日中见沫，折其右肱，无咎。 象曰：“丰其沛”，不可大事也。“折其右肱”，终不可用也。 <a class="header-anchor" href="#九三-丰其沛-日中见沫-折其右肱-无咎。-象曰-丰其沛-不可大事也。-折其右肱-终不可用也。" aria-label="Permalink to “九三，丰其沛，日中见沫，折其右肱，无咎。 象曰：“丰其沛”，不可大事也。“折其右肱”，终不可用也。”">​</a></h3><p>所应在阴，故曰“丰沛”。能折其右肱，绝去上六而不累其明，则可免咎也。光大之上，阴柔之终，不可用也。</p><h3 id="九四-丰其蔀-日中见斗-遇其夷主-吉。-象曰-丰其蔀-位不当也-日中见斗-幽不明也-遇其夷主-吉行也。" tabindex="-1">九四，丰其蔀，日中见斗，遇其夷主，吉。 象曰：“丰其蔀”，位不当也；“日中见斗”，幽不明也；“遇其夷主”，吉行也。 <a class="header-anchor" href="#九四-丰其蔀-日中见斗-遇其夷主-吉。-象曰-丰其蔀-位不当也-日中见斗-幽不明也-遇其夷主-吉行也。" aria-label="Permalink to “九四，丰其蔀，日中见斗，遇其夷主，吉。 象曰：“丰其蔀”，位不当也；“日中见斗”，幽不明也；“遇其夷主”，吉行也。”">​</a></h3><p>无应于下，近比于五，故亦云“见斗”；正应亦阳，故云“夷主”。</p><h3 id="六五-来章-有庆誉-吉。-象曰-六五之吉-有庆也。" tabindex="-1">六五，来章，有庆誉，吉。 象曰：六五之吉，有庆也。 <a class="header-anchor" href="#六五-来章-有庆誉-吉。-象曰-六五之吉-有庆也。" aria-label="Permalink to “六五，来章，有庆誉，吉。 象曰：六五之吉，有庆也。”">​</a></h3><p>来章，反比阳则明也；有庆，得配于四也。</p><h3 id="上六-丰其屋-蔀其家-窥其户-阒其无人-三岁不觌-凶。-象曰-丰其屋-天际翔也-窥其户-阒其无人-自藏也。" tabindex="-1">上六，丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。 象曰：“丰其屋”，天际翔也；“窥其户，阒其无人”，自藏也。 <a class="header-anchor" href="#上六-丰其屋-蔀其家-窥其户-阒其无人-三岁不觌-凶。-象曰-丰其屋-天际翔也-窥其户-阒其无人-自藏也。" aria-label="Permalink to “上六，丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。 象曰：“丰其屋”，天际翔也；“窥其户，阒其无人”，自藏也。”">​</a></h3><p>丰屋蔀家，自蔽之甚，犹大明之世而夷墨其行，穷大而失居者也。处上之极，不交于下而居动之末，故曰“天际翔”也。</p>',18)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
